                "/api/experiments/D-3/participants/PA/disclosures", HttpMethod.POST,
                headers("coord-1", "COMPLIANCE", "d3-compliance"),
                "{\"exposureKey\":\"EX-22\",\"targetActorIds\":[\"op-a\"]}")
                .getStatusCode().value());

