                "SELECT COUNT(*) FROM disclosure_edge WHERE experiment_id = 'D-3'", Integer.class));
        assertEquals(0, jdbc.queryForObject(
                "SELECT COUNT(*) FROM closure_version WHERE experiment_id = 'D-3'", Integer.class));
