        assertEquals(200, rest.exchange("/api/unblind-requests/" + ubId + "/approval",
                HttpMethod.POST, new HttpEntity<>(null,
                        headers("rev-2", "REVIEWER", prefix + "-approve")), String.class)
                .getStatusCode().value());
